// Signs Android release builds with the Play upload key.
//
// The android/ folder is generated by `npx expo prebuild`, so the signing setup
// lives here instead of being edited into android/app/build.gradle by hand.
// Keystore path and passwords are read from Gradle properties, normally in
// ~/.gradle/gradle.properties (outside the repo). With { prefix: "ETF_UPLOAD" }:
//
//   ETF_UPLOAD_STORE_FILE=/absolute/path/to/etf-percentile.keystore
//   ETF_UPLOAD_KEY_ALIAS=etf-percentile
//   ETF_UPLOAD_STORE_PASSWORD=...
//   ETF_UPLOAD_KEY_PASSWORD=...
//
// Usage in app.config.js:  [withReleaseSigning, { prefix: "ETF_UPLOAD" }]
//
// Without them, release builds fall back to the debug key (fine for local
// testing; Play Console will reject such a bundle).
const { withAppBuildGradle } = require("@expo/config-plugins");

const MARKER = "// [with-release-signing]";

const releaseSigning = (p) => `
        release {
            ${MARKER}
            if (project.hasProperty('${p}_STORE_FILE')) {
                storeFile file(${p}_STORE_FILE)
                storePassword ${p}_STORE_PASSWORD
                keyAlias ${p}_KEY_ALIAS
                keyPassword ${p}_KEY_PASSWORD
            }
        }`;

function addReleaseSigning(gradle, prefix) {
  if (gradle.includes(MARKER)) {
    return gradle;
  }

  // 1. Add a `release` signing config next to the template's `debug` one.
  const signingConfigs = /signingConfigs\s*\{\s*\n(\s*)debug\s*\{[^}]*\}/m;
  if (!signingConfigs.test(gradle)) {
    throw new Error("with-release-signing: signingConfigs.debug not found in app/build.gradle");
  }
  gradle = gradle.replace(signingConfigs, (match) => match + releaseSigning(prefix));

  // 2. Use it for the release build type when the upload key is configured.
  const releaseBuildType = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/m;
  if (!releaseBuildType.test(gradle)) {
    throw new Error("with-release-signing: release build type not found in app/build.gradle");
  }
  return gradle.replace(
    releaseBuildType,
    `$1signingConfig project.hasProperty('${prefix}_STORE_FILE') ? signingConfigs.release : signingConfigs.debug`,
  );
}

module.exports = function withReleaseSigning(config, { prefix = "UPLOAD" } = {}) {
  return withAppBuildGradle(config, (modConfig) => {
    modConfig.modResults.contents = addReleaseSigning(modConfig.modResults.contents, prefix);
    return modConfig;
  });
};
